if (localStorage.values.apiKey == '') {
  txtApiKey.setValue('**ENTER API KEY HERE**');
  return;
} 
let vehicles = [];
let shifts = [];
let starts = [];
let ends = [];
let veh_attr = [];
let stop_attr = [];
let shiftStart = (new Date(dtShiftStart.value).getTime()/1000);
let shiftEnd = (new Date(dtShiftEnd.value).getTime()/1000);

// START NBAI PROBLEM BUILD
let locations = [];
let jobs = [];
vehicles = [];
veh_attr = [];
stop_attr = [];
// sequence through all stops and create job array while
// also creating the indexed list of locations 
let location_index = 0;
let location = [];
let id = 1;

table3.selectedRows.forEach( planstop => {

    let job = {
      id: id++,
      description: planstop.msdyn_workorderid,
      location_index: location_index++,
      service: planstop.msdyn_totalestimatedduration*60,
      priority: 0,
      time_windows: [[shiftStart,shiftEnd]]
    }
    location.push(`${planstop.msdyn_latitude},${planstop.msdyn_longitude}`);

    jobs.push(job);

});

// Add shift start/stop location to location index
location.push(`${txtVehicleStartPosition.value}`);
location_index += 1;
location.push(`${txtVehicleEndPosition.value}`);
let vehicle_id = 1;
table4.selectedRows.forEach( v => {
  let vehicle = {
    id: vehicle_id++,
    description: v.bookableresourceid,
    start_index: location_index,
    end_index: location_index,
    time_window: [shiftStart, shiftEnd],
    max_tasks: 25
  };
  vehicles.push(vehicle);


});

locations = {
  id: 12,
  description: 'NB.AI D365 DEMO',
  location: location
};

let options = {
  routing: {
    mode: '4w'
  }
};

localStorage.setValue('vehiclesNBAI', vehicles);
localStorage.setValue('jobsNBAI', jobs);
localStorage.setValue('locationsNBAI', locations);
localStorage.setValue('nbaiVRPResult', null);
localStorage.setValue('nbaiOptions', options);
let vrpProblemNBAI = {
  locations: localStorage.values.locationsNBAI,
  jobs: localStorage.values.jobsNBAI,
  vehicles: localStorage.values.vehiclesNBAI,
  departure_time: 0
};
localStorage.setValue('vrpProblemNBAI', vrpProblemNBAI);

nbaiOptimizationRun.trigger();
```

## Step 1: Extract Relevant Data from NextBillion.ai Result

First, retrieve the optimization result data, including the routes, from the NextBillion.ai API response.

```javascript
const nbaiResult = nbaiOptimizationStatus.data.result;
const routes = nbaiResult.routes;
```

## Step 3: Get Zone IDs from Dropdowns

Retrieve the zone IDs for the start and end locations from dropdown elements.

```javascript
const startZoneId = select1.value;
const endZoneId = select2.value;
```

```javascript
const postRequestBody = {
    method: "ADD",
    params: {
        typeName: "Route",
        entity: {
            comment: "GeoTab_Nb_Integration",
            name: routes[0].description,
            routePlanItemCollection: routes[0].steps.map((step, index) => ({
                activeFrom: dtShiftStart2.value,
                activeTo: dtShiftEnd2.value,
                dateTime: dtShiftStart2.value,
                comment: "",
                expectedDistanceToArrival: convertToMiles(step.distance),
                expectedStopDuration: new Date(step.service * 1000).toISOString().substr(11, 8),
                expectedTripDurationToArrival: new Date(step.duration * 1000).toISOString().substr(11, 8),
                sequence: index,
                zone: {
                    id: (index === 0) ? startZoneId : (index === routes[0].steps.length - 1) ? endZoneId : step.description
                }
            })),
            routeType: "Basic",
            startTime: dtShiftStart2.value,
            endTime: dtShiftEnd2.value
        },
        credentials: {
            "database": "geotab_database",
            "sessionId": "session_id",
            "userName": "user_name"
        }
    }
};
```

