class OfflineMapActivity : AppCompatActivity() {
    private lateinit var mapView: MapView
    private var map: NextbillionMap? = null

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_offline_map)

        mapView = findViewById(R.id.mapView)
        mapView.onCreate(savedInstanceState)
        mapView.getMapAsync { nextbillionMap ->
            map = nextbillionMap

            val styleUri = Style.getPredefinedStyle("Bright")
            nextbillionMap.setStyle(Style.Builder().fromUri(styleUri)) {
                intent.getIntExtra("region_id", -1)
                    .takeIf { it >= 0 }
                    ?.let { previewInstalledRegion(nextbillionMap, it) }
            }
        }
    }

    private fun previewInstalledRegion(map: NextbillionMap, regionId: Int) {
        lifecycleScope.launch {
            val installed = withContext(Dispatchers.IO) {
                RegionalOffline.listInstalledRegions()
                    .any { it.regionId == regionId }
            }
            val focused = installed &&
                RegionalOffline.focusPreviewRegion(map, regionId)
            if (!focused) showRegionBoundsUnavailable()
        }
    }

    override fun onStart() {
        super.onStart()
        mapView.onStart()
    }

    override fun onResume() {
        super.onResume()
        mapView.onResume()
    }

    override fun onPause() {
        mapView.onPause()
        super.onPause()
    }

    override fun onStop() {
        mapView.onStop()
        super.onStop()
    }

    override fun onLowMemory() {
        super.onLowMemory()
        mapView.onLowMemory()
    }

    override fun onSaveInstanceState(outState: Bundle) {
        super.onSaveInstanceState(outState)
        mapView.onSaveInstanceState(outState)
    }

    override fun onDestroy() {
        map = null
        mapView.onDestroy()
        super.onDestroy()
    }
}
