class App : Application() {
    override fun onCreate() {
        super.onCreate()

        Nextbillion.getInstance(
            this,
            BuildConfig.NEXTBILLION_API_KEY,
            NGLWellKnownTileServer.NGLTomTom,
        )

        when (RegionalOffline.supportStatus()) {
            RegionalOfflineSupportStatus.SUPPORTED -> {
                if (!RegionalOffline.initialize(this)) {
                    Log.e("App", "Regional Offline initialization failed")
                }
            }
            RegionalOfflineSupportStatus.TOMTOM_REQUIRED ->
                Log.w("App", "Regional Offline requires NGLTomTom")
            RegionalOfflineSupportStatus.NEXTBILLION_NOT_INITIALIZED ->
                Log.e("App", "Initialize Nextbillion before Regional Offline")
        }
    }
}
