private fun renderPreviewBundleStatus(status: PreviewBundleImportStatus) {
    when {
        status.previewBundleReady -> showPreviewReady()
        status.waitingForNetwork -> showWaitingForNetwork()
        status.ensuring -> showPreparingResources()
        status.lastErrorCode != null -> showPreviewPreparationError(status.recoverable)
    }
}
